actions.script:
if (!WebUtilities.isSafeSinglePathSegment(filename)) {
    ec.web.sendJsonError(404, "Snapshot not found")
} else {
    ec.web.sendResourceResponse("runtime://db/snapshot/" + filename)
}

const importParameters = {zipFilename, dummyFks: String(context.dummyFks) == 'true', useTryInsert: String(context.useTryInsert) == 'true',
    disableEntityEca: String(context.disableEntityEca) != 'false', disableAuditLog: String(context.disableAuditLog) != 'false',
    disableFkCreate: String(context.disableFkCreate) != 'false', disableDataFeed: String(context.disableDataFeed) != 'false',
    transactionTimeout: parseInt(context.transactionTimeout || '3600', 10)}
if (String(context.wrapForeignKeys) != 'true') {
    jobRunId = ec.service.job("ImportEntityDataSnapshot").parameters(importParameters).run()
    ec.message.addMessage(`Started Import Entity Data Snapshot ${zipFilename} (Job ID ${jobRunId})`)
    return
}
if (!ec.user.hasPermission('DATABASE_ADMIN')) { ec.message.addError(ec.l10n.localize('A load with the foreign keys dropped needs the DATABASE_ADMIN permission')); return }
// the entities of the snapshot: its files, one per entity when it was exported that way, named in the zip's
// directory at its end; a snapshot of one file names none, and then every key of the database is dropped
const location = 'runtime://db/snapshot/' + zipFilename
const size = Number(ec.resource.getLocationReference(location)?.getSize() || 0)
const names = new Set()
let offset = Math.max(0, size - 4 * 1024 * 1024)
for (let reads = 0; reads < 64; reads++) {
    const part = ec.resource.readLines(location, offset, 5000, 1024 * 1024)
    for (const line of part.lines || []) for (const match of String(line).matchAll(/([A-Za-z_][\w.]*)\.(xml|json|csv)/g))
        if (ec.entity.isEntityDefined(match[1])) names.add(match[1])
    if (part.done || part.nextOffset == null || part.nextOffset <= offset) break
    offset = part.nextOffset
}
const entityNames = Array.from(names)
if (!entityNames.length) ec.message.addMessage(ec.l10n.localize('The snapshot is one file, not one per entity: every foreign key of the database is dropped around it'), 'warning')
const wrap = ec.service.sync().name('org.moqui.dev.DatabaseServices.plan#LoadWrap').parameters({db, entityNames,
    description: 'Foreign keys around the import of ' + zipFilename}).call() || {}
if (ec.message.hasError()) return
for (const warning of wrap.warnings || []) ec.message.addMessage(String(warning), 'warning')
if (!wrap.dropJobId || !wrap.restoreJobId) { ec.message.addError(String(wrap.jobReason || 'The foreign keys could not be planned')); return }
jobRunId = ec.service.job('DatabaseLoadWrap').parameters(Object.assign({dropJobId: wrap.dropJobId, restoreJobId: wrap.restoreJobId,
    loadKind: 'snapshot'}, importParameters)).run()
ec.message.addMessage(`Started the import of ${zipFilename} on a worker (job run ${jobRunId}): database job ${wrap.dropJobId} drops ${(wrap.dropStatements || []).length} foreign keys, then the snapshot is imported, then database job ${wrap.restoreJobId} makes them again. A notification says how it ended; Database › Jobs shows both jobs.`, 'info')

const filename = WebUtilities.lastPathSegment(snapshotFile.getName())
if (!filename?.endsWith(".zip") || !WebUtilities.isSafeSinglePathSegment(filename)) {
    ec.message.addError(`File ${filename} is not a zip file, should be a zip containing one or more xml data files`); return
}
// written beside the exported snapshots, where Import finds it; one of the same name is replaced
const stream = snapshotFile.getInputStream()
try { ec.resource.getLocationReference('runtime://db/snapshot/' + filename).putStream(stream) }
finally { if (stream && stream.close) stream.close() }
ec.message.addMessage(ec.resource.expand('Uploaded snapshot ${filename}', '', {filename: filename}))

const snapshotDir = ec.resource.getLocationReference('runtime://db/snapshot')
snapshotList = []
if (snapshotDir != null && snapshotDir.exists) for (const sfile of snapshotDir.getDirectoryEntries())
    if (!sfile.isDirectory() && sfile.fileName.endsWith(".zip") && sfile.getSize() > 0)
        snapshotList.push({name: sfile.fileName, lastModified: sfile.getLastModified(), size: sfile.getSize()})
